    LANGUAGE_WRAPPER = 'A three-outcome device produces A, B, or C with probabilities (p_A, p_B, p_C) drawn at random from a Dirichlet distribution with integer shape parameters {a_shape}, {b_shape}, and {c_shape}. The device is run for {n_trials} independent emissions. Let E be the event that exactly {c_target} emissions are C and the numbers of A and B emissions are equal. If the probability of E equals m/n in lowest terms, find m+n.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
import math
from fractions import Fraction

def prob(a,b,c,n,t):
    k = (n - t)//2
    frac = Fraction(math.factorial(n), math.factorial(k)*math.factorial(k)*math.factorial(t))
    frac *= Fraction(math.factorial(a + b + c - 1), math.factorial(a + b + c + n - 1))
    frac *= Fraction(math.factorial(a + k - 1), math.factorial(a - 1))
    frac *= Fraction(math.factorial(b + k - 1), math.factorial(b - 1))
    frac *= Fraction(math.factorial(c + t - 1), math.factorial(c - 1))
    return frac

for _ in range(1000):
    n = rng.randint(42, 86)
    a = rng.randint(2, 6)
    b = rng.randint(2, 6)
    c = rng.randint(2, 6)
    if a == b == c:
        continue
    t = rng.randint(1, n - 1)
    if (n - t) % 2 != 0:
        continue
    k = (n - t)//2
    if k <= 0:
        continue
    P = prob(a,b,c,n,t)
    den = P.denominator
    # enforce difficulty: denominator neither tiny nor astronomical, and probability not trivial
    if den <= 5000:
        continue
    if den > 10**16:
        continue
    if P <= Fraction(1, 10**8):
        continue
    if P >= Fraction(1, 10):
        continue
    return {'a_shape': a, 'b_shape': b, 'c_shape': c, 'n_trials': n, 'c_target': t}

# Fallback (rare): deterministic parameters satisfying constraints
a,b,c = 2,3,5
n = 60
t = 14  # n - t = 46 => k = 23 > 0
return {'a_shape': a, 'b_shape': b, 'c_shape': c, 'n_trials': n, 'c_target': t}

